INSERT IGNORE INTO scene_questions (id, category, difficulty, scene_text, options_json, hint, source, enabled) VALUES
('SC001', '礼品礼金', 1, '项目验收在即，长期合作的供应商负责人私下递来一张购物卡，笑着说：“就是过节的一点心意，不影响验收，您放心。”', '[{"key":"a","text":"收下，反正是老供应商，验收按标准来，不影响公事。","pot":"corrupt"},{"key":"b","text":"不收卡，但让对方折算成项目里的“增值服务”补回来。","pot":"edge"},{"key":"c","text":"明确拒绝，并提醒对方这是违规送礼，验收会严格按合同执行。","pot":"clean"}]', '违规收受礼品礼金违反中央八项规定精神，“不影响验收”本身就是影响——拿了东西，标准就难再硬。', 'internal', 1),
('SC002', '采购招标', 2, '立项论证时你发现，只有 A 公司的产品“恰好”完全满足技术参数，其他厂商都差一点，而你清楚这套参数是上任按 A 公司产品量身写的。', '[{"key":"a","text":"维持参数不变，直接走单一来源采购 A 公司，省事省力。","pot":"corrupt"},{"key":"b","text":"名义上组织询价，但参数不动，等于内定 A 公司。","pot":"edge"},{"key":"c","text":"重新论证参数合理性，去掉排他性条款，真正开放竞争。","pot":"clean"}]', '为特定供应商“量身定制”参数属于规避竞争、涉嫌利益输送，违反采购与廉洁从业相关规定。', 'internal', 1),
('SC003', '宴请旅游', 1, '外包团队负责人请你吃饭，席间频频举杯，最后委婉提出：“下一期项目还想继续跟您合作，还请多关照。”', '[{"key":"a","text":"欣然应允，暗示只要“意思到位”，下期合作没问题。","pot":"corrupt"},{"key":"b","text":"饭照吃，话不说死，只说“按流程来”，让对方觉得有空间。","pot":"edge"},{"key":"c","text":"主动结账或拒绝宴请，说明合作只看能力与报价，不接受私下请托。","pot":"clean"}]', '违规接受可能影响公正履职的宴请属于违规吃喝。吃人的嘴软，含糊其辞本身就是默许。', 'internal', 1),
('SC004', '履职验收', 2, '项目赶工，供应商主动提出：“反正功能都实现了，验收文档我们帮您一起‘处理’，保证通过，您也省心。”', '[{"key":"a","text":"让供应商代写验收材料，自己只负责签字，图个清闲。","pot":"corrupt"},{"key":"b","text":"自己写主报告，但默许供应商“优化”测试用例和数据。","pot":"edge"},{"key":"c","text":"拒绝代笔，坚持亲自核验功能并如实撰写验收结论。","pot":"clean"}]', '验收造假、让被监督对象代写结论，既失职渎职又埋下质量隐患，一旦出事责任全在你。', 'internal', 1),
('SC005', '数据造假', 2, '数据标注外包方提出，可以“优化”一下人效数据，让季度报表的投入产出比更好看，领导满意、部门加分。', '[{"key":"a","text":"同意优化，报表好看最重要，反正不影响业务实质。","pot":"corrupt"},{"key":"b","text":"不直接造假，但对明显虚高的数据睁一只眼闭一只眼。","pot":"edge"},{"key":"c","text":"坚决拒绝，坚持用真实数据，必要时主动向上级说明情况。","pot":"clean"}]', '数据造假、虚报业绩违反诚实守信与如实报告义务，是典型的弄虚作假，一查必究。', 'internal', 1),
('SC006', '利益输送', 1, '云资源采购谈判中，供应商私下提出：“按采购额给您返点，直接打到您亲属账户，绝对安全，合规无忧。”', '[{"key":"a","text":"把返点打入亲属账户，认为“不是自己名下”就没事。","pot":"corrupt"},{"key":"b","text":"不直接收钱，但让对方以“合作咨询费”名义支付给亲属。","pot":"edge"},{"key":"c","text":"当场拒绝并留存证据，向上级或纪检部门报告该供应商。","pot":"clean"}]', '通过亲属账户收受回扣是典型商业贿赂，“打别人账户”改变不了受贿性质，甚至更恶劣。', 'internal', 1),
('SC007', '商业秘密', 2, '投标截止前，你收到一份匿名快递，里面是竞争对手的详细报价单，明显是有人想“帮”你。', '[{"key":"a","text":"打开研究并据此调整自家报价，认为“机会来了”。","pot":"corrupt"},{"key":"b","text":"不主动使用，但不销毁、不报告，揣在手里当“备胎”。","pot":"edge"},{"key":"c","text":"原封不动上报纪检或招投标监督部门，绝不利用。","pot":"clean"}]', '利用非法获取的商业秘密属于不正当竞争，知情不报、留存待用同样是违纪的“灰色”操作。', 'internal', 1),
('SC008', '人事关系', 2, '上级领导打电话：“某家供应商技术确实不错，这次你多关照一下，别让我为难。”', '[{"key":"a","text":"照领导意思办，直接向该供应商倾斜，反正“有领导担着”。","pot":"corrupt"},{"key":"b","text":"给个“象征性”机会，但暗中在评分上给予照顾。","pot":"edge"},{"key":"c","text":"如实说明会按制度和程序公平评审，并做好相关记录备查。","pot":"clean"}]', '领导干部违规插手干预采购是明令禁止的，“有领导担着”不成立，经办人同样要担责。', 'internal', 1),
('SC009', '津贴补贴', 2, '项目奖金分配时，你是牵头人，团队里没人会细算，“给自己多留一点，反正没人知道”这个念头闪过。', '[{"key":"a","text":"做两套账，给自己多报一块，神不知鬼不觉。","pot":"corrupt"},{"key":"b","text":"不虚报，但把团队贡献有意往自己头上多算几分。","pot":"edge"},{"key":"c","text":"按实际贡献和既定规则公开、公平分配，接受大家监督。","pot":"clean"}]', '“没人知道”是最危险的侥幸。克扣、侵占团队应得利益，是违纪也是失德。', 'internal', 1),
('SC010', '宴请旅游', 1, '供应商邀请你参加“技术考察”，行程单上除了半天参观，剩下五天都是三亚的酒店和景点。', '[{"key":"a","text":"愉快前往，反正是对方出钱，“考察”只是名目。","pot":"corrupt"},{"key":"b","text":"婉拒全程，但同意让供应商承担往返和住宿“考察”费用。","pot":"edge"},{"key":"c","text":"拒绝此类变相旅游，如确有需要，按规定由本单位审批并承担费用。","pot":"clean"}]', '以考察之名行旅游之实，属于变相公款旅游、接受可能影响公正履职的安排，违反中央八项规定精神。', 'internal', 1),
('SC011', '履职验收', 1, '验收时发现几处功能缺陷，供应商拍胸脯：“小问题，先签了，我们后面保证补上。”', '[{"key":"a","text":"直接签字通过，反正是“小问题”，后面补不补再说。","pot":"corrupt"},{"key":"b","text":"签字但口头约定限期整改，不写入验收记录。","pot":"edge"},{"key":"c","text":"拒签，将缺陷书面记录并要求整改完成后再验收。","pot":"clean"}]', '“先签后补”往往“签了就没了”。验收放水是失职，口头承诺不落纸等于没有约束。', 'internal', 1),
('SC012', '履职验收', 2, '你发现外包团队报上来的工作量明显虚高，但“大家都这样”，前任也这么默许过来了。', '[{"key":"a","text":"默许虚报，甚至配合在确认单上签字，大家心照不宣。","pot":"corrupt"},{"key":"b","text":"不签字但也不纠正，装作没看见，维持现状。","pot":"edge"},{"key":"c","text":"核实真实工作量，坚决核减虚报部分，并向相关负责人说明。","pot":"clean"}]', '“大家都这样”不能成为违纪理由。对虚报失察、默许，属于监督失职，可能被认定为共谋。', 'internal', 1),
('SC013', '利益输送', 2, '供应商提出：“我们有一笔‘咨询费’，按合规流程走，直接打到您亲属账户，您放心。”', '[{"key":"a","text":"答应下来，认为“合规流程”四个字就是护身符。","pot":"corrupt"},{"key":"b","text":"不拒绝，但先“观望”，等供应商把流程“做漂亮”了再收。","pot":"edge"},{"key":"c","text":"识破这是变相利益输送，明确拒绝并远离。","pot":"clean"}]', '“合规流程”是行贿话术，绕过本人收受亲属账户财物，本质仍是受贿，且是处心积虑的隐蔽形式。', 'internal', 1),
('SC014', '履职验收', 3, '项目结算时，你发现财务系统里有一笔费用重复计了，金额不小，而财务尚未察觉。', '[{"key":"a","text":"默不作声，事后想办法把多出的钱“处理”到自己的渠道。","pot":"corrupt"},{"key":"b","text":"不主动揭发，但也不动这笔钱，等它自己“过去”。","pot":"edge"},{"key":"c","text":"立即指出重复计费，主动纠正，避免国有资产损失。","pot":"clean"}]', '发现差错不纠正、甚至想据为己有，性质从失察滑向侵占，一念之差就是违纪与犯罪的界线。', 'internal', 1),
('SC015', '商业秘密', 2, '手头能导出大量客户数据，你觉得“脱敏了应该没事”，想拿来做自己接的私活项目。', '[{"key":"a","text":"直接导出使用，认为脱敏后“谁也查不出来”。","pot":"corrupt"},{"key":"b","text":"只导出“看起来”不敏感的字段，自认为安全。","pot":"edge"},{"key":"c","text":"严守数据权限，不因私利触碰任何客户数据，涉及使用一律走合规审批。","pot":"clean"}]', '违规使用、泄露数据违反数据安全与保密规定，“脱敏”不等于“安全”，一旦泄露追责到个人。', 'internal', 1),
('SC016', '采购招标', 3, '技术选型上你清楚 A 方案明显更优，但 B 厂商与你有私下的利益往来，天平在心里悄悄偏了。', '[{"key":"a","text":"在评审报告中把 B 写成更优，让“技术论证”为私利背书。","pot":"corrupt"},{"key":"b","text":"不明确偏向，但在评分细节上给 B 找“合理理由”加分。","pot":"edge"},{"key":"c","text":"如实按技术优劣与成本效益做结论，主动回避涉及利益关系的厂商。","pot":"clean"}]', '用专业话语包装利益输送，是最隐蔽也最危险的腐败。技术决策一旦夹带私货，损害的是公共利益。', 'internal', 1),
('SC017', '津贴补贴', 2, '供应商私下说：“你们团队加班辛苦，加班费我们想办法从项目里‘补贴’，别走正规流程了。”', '[{"key":"a","text":"同意让供应商以项目款名义变相发补贴。","pot":"corrupt"},{"key":"b","text":"不直接同意，但默许供应商给个别骨干“单独表示”。","pot":"edge"},{"key":"c","text":"拒绝，说明加班费应按规定由单位足额发放，不接受变相补贴。","pot":"clean"}]', '以项目款变相发放补贴，绕开财务制度，是违规发放津补贴与利益输送的叠加。', 'internal', 1),
('SC018', '礼品礼金', 1, '项目刚中标，供应商送来一套“纪念品”，包装精美，说“纯属感谢，不值钱，就是份心意”。', '[{"key":"a","text":"收下纪念品，觉得“中标是公平竞争，收点心意无所谓”。","pot":"corrupt"},{"key":"b","text":"先收下，等看清价值再决定是否退回。","pot":"edge"},{"key":"c","text":"婉拒并退回，说明廉洁纪律要求不收受供应商任何礼品。","pot":"clean"}]', '中标后收受供应商礼品，是“事后感谢”式利益输送，看似小事，实则打开了围猎的口子。', 'internal', 1);
INSERT IGNORE INTO quiz_questions (id, category, difficulty, scene, compliant, answer_note, explain_text, basis, enabled) VALUES
('QZ001', '人情往来', 2, '同事结婚，你随礼 500 元；你结婚时，同事也回随了 500 元。', 1, '能随能收', '正常同事关系、有来有往、金额符合当地人情水平，属于正常礼尚往来。纪律约束的是“利用职权借机敛财”和“明显超出正常往来”，不是正常人情。', '《中国共产党纪律处分条例》第九十七条、第一百条', 1),
('QZ002', '津贴补贴', 2, '中秋节前，单位工会给每名职工发了一桶油、一盒月饼。', 1, '能收', '符合规定的工会节日慰问属于职工正当福利。判断要点：发放主体是工会、经费来源合规、标准在规定范围内、全员普惠。', '《基层工会经费收支管理办法》（总工办发〔2017〕32 号）', 1),
('QZ003', '礼品礼金', 2, '你在商场消费后参加公开抽奖，中了一部手机。', 1, '能收', '面向不特定社会公众、机会均等、与个人职权毫无关联的中奖所得，不属于违纪所得。关键判断点：抽奖机会是否人人平等、是否与你的职务身份挂钩。', '《中国共产党纪律处分条例》第九十七条', 1),
('QZ004', '兼职取酬', 2, '经单位批准，你利用业余时间为高校培训班授课，按标准领取讲课费 2000 元。', 1, '能收', '经组织批准、实际提供了劳务、报酬在标准范围内，属于合法劳动报酬。红线在于：未经批准兼职取酬、挂名不干活领酬、超出规定标准取酬。', '《中国共产党纪律处分条例》第一百零三条', 1),
('QZ005', '人情往来', 2, '老家发小（在家务农，与你的工作毫无交集）寄来两袋自家种的花生。', 1, '能收', '对方与你的职权、管辖范围无任何交集，物品价值微小，属于正常亲友往来。判断三问：对方是谁、图什么、值多少——三问均无红灯。', '《中国共产党纪律处分条例》第九十七条', 1),
('QZ006', '生活作风', 2, '国庆假期，你自费带家人旅游，入住了高档酒店。', 1, '可以', '花自己的钱、休假期间、不与管理服务对象同行、不影响公务，属于个人消费自由。享乐主义、奢靡之风针对的是挥霍公款或造成不良影响的消费。', '中央八项规定精神；《中国共产党纪律处分条例》第一百五十条', 1),
('QZ007', '人情往来', 2, '你孩子结婚，事前按规定向组织报备，婚宴控制在规定桌数内，来宾均为亲友、无管理服务对象，亲友们正常随礼。', 1, '能收', '婚丧喜庆本身可以办，违规的是不报备、超规模、邀请管理服务对象、借机敛财。做到“报备 + 控规模 + 不请管理服务对象”，正常亲友随礼可以收。', '《中国共产党纪律处分条例》第一百条', 1),
('QZ008', '宴请接待', 3, '大学同学聚会，AA 制聚餐。同学中有一人是你单位的供应商，但全程叙旧、不谈业务、费用均摊。', 1, '可以参加', '私人情谊、自己买单、无请托事项、未影响公正执行公务，不属于违纪。但要有边界意识：聚会中不谈工作、不接受对方单独买单、事后不因私交在业务上给予关照。', '《中国共产党纪律处分条例》第一百零一条', 1),
('QZ009', '礼品礼金', 1, '微信群里抢了一个 8 毛钱的拼手气红包，群主是你单位的供应商，群里多为业务往来对象。', 0, '不能收', '电子红包是隐形变异送礼的典型形态，金额再小不改变性质——8 毛钱的背后是“试探”和“铺路”。正确做法：不抢，已抢的退回或上交。', '《中国共产党纪律处分条例》第九十七条；中央八项规定精神', 1),
('QZ010', '借用财物', 1, '供应商说“公司这辆车反正闲着，你先开着用”，借给你使用半年。', 0, '不能借、不能用', '“借”是名义，“输送利益”是实质。借用管理和服务对象的钱款、住房、车辆等，本身就是违纪，不论是否归还、是否付油费。', '《中国共产党纪律处分条例》第九十九条', 1),
('QZ011', '借用财物', 2, '你买房缺首付，向供应商借款 50 万，打了借条，约定按银行利率付利息。', 0, '不能借', '手续齐全不改变性质。向管理服务对象借贷，对方图的是你的职权，利息只是遮羞布。通过民间借贷获取大额回报、影响公正执行公务的，明令禁止。', '《中国共产党纪律处分条例》第九十九条', 1),
('QZ012', '利益输送', 2, '供应商没送一分钱，但打了个电话，帮你孩子安排进知名券商实习。', 0, '不能接受', '“机会”也是利益。权钱交易早已不限于现金和实物，入学、就业、就医、晋升等非物质利益同样是利益输送的常见标的。', '《中国共产党纪律处分条例》第九十四条；受贿罪司法解释中“财产性利益”的认定', 1),
('QZ013', '宴请接待', 2, '你自掏腰包，请管理服务对象在人均 2000 元的餐厅吃饭，联络感情。', 0, '不能', '谁买单不改变性质。条例同时约束“接受”和“提供”可能影响公正执行公务的宴请——你请对方，同样可能构成“提供可能影响公正执行公务的宴请”。', '《中国共产党纪律处分条例》第一百零一条', 1),
('QZ014', '礼品礼金', 1, '项目验收完、款项全部结清，合作方寄来一盒茶叶，附言“感谢支持，后会有期”。', 0, '不能收', '“事后感谢”是围猎的常见话术。业务虽结束，但你的职务影响力仍在，对方感谢的从来不是你这个人，而是你的岗位。且“后会有期”说明对方在为下一次合作铺路。', '《中国共产党纪律处分条例》第九十七条', 1),
('QZ016', '礼品礼金', 3, '市场价 300 万的房子，供应商以 240 万“优惠价”卖给你，你签订了正规购房合同。', 0, '不能买（交易型受贿）', '付了钱不等于合法。以明显低于市场价格向请托人购买房屋、汽车等物品，差价部分即为受贿数额，这叫“交易型受贿”。', '《刑法》第三百八十五条；“两高”关于以交易形式收受贿赂的司法解释', 1),
('QZ017', '礼品礼金', 2, '朋友送你一幅字画，说“地摊上买的，不值钱”。经鉴定，实为名家真迹，价值数十万元。', 0, '不能收（雅贿）', '“雅贿”按物品实际价值认定，“不知道值钱”不构成免责理由。收受字画、古董、玉石等“雅贿”，是近年通报的高频形态。', '《中国共产党纪律处分条例》第九十七条', 1),
('QZ019', '礼品礼金', 2, '你已退休三年。当年你一手提拔的老下属如今是老板，春节提着贵重节礼登门拜年。', 0, '不能收（期权腐败）', '退休不是“安全着陆”。离职或者退（离）休后利用原职权或职务上的影响收受财物、为他人谋利，属于“期权腐败”，照样追究党纪直至刑事责任。', '《中国共产党纪律处分条例》第一百零六条；《刑法》第三百八十八条之一', 1),
('QZ022', '人情往来', 3, '十年没联系的大学同学，去年刚中标你们单位的项目。今年春节他提着两瓶酒上门，说“老同学叙叙旧”。', 0, '不能收', '同学情谊是真的，但他现在的身份是你的管理服务对象，送礼时点又在节日前——“叙旧”与“铺路”无法切割。正确做法：情可以叙，礼不能收，当场婉拒。', '《中国共产党纪律处分条例》第九十七条', 1),
('QZ025', '人情往来', 2, '下属给你孩子的满月红包里包了 2000 元，远超当地正常随礼水平。', 0, '不能收', '上下级之间存在职务上的管理关系，“明显超出正常礼尚往来”的礼金即踩红线。金额是否“明显超出”，参照当地正常人情水平判断。', '《中国共产党纪律处分条例》第九十七条', 1);
